// ❌ REACT: useEffect with empty dependency array runs after render and paint,
// but executes twice in development under StrictMode, confusing developers.
import { useState, useEffect } from 'react';

export default function TimerReact() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setSeconds(s => s + 1), 1000);
    return () => clearInterval(id);
  }, []);

  return <div>Seconds: {seconds}</div>;
}

// ✅ SOLIDJS: onMount runs once when DOM is ready.
// onCleanup can be declared anywhere inside the component scope.
import { createSignal, onMount, onCleanup } from 'solid-js';

export default function TimerSolid() {
  const [seconds, setSeconds] = createSignal(0);

  onMount(() => {
    console.log('DOM is mounted and ready for measurement!');
  });

  const timerId = setInterval(() => setSeconds(s => s + 1), 1000);

  // ✅ Automatically executes when TimerSolid unmounts:
  onCleanup(() => {
    clearInterval(timerId);
  });

  return <div>Seconds: {seconds()}</div>;
}
